window.__finlexDocLoaded(10160,{"id":10160,"articles":[{"id":1000673,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Global template for bilateral double taxation treaties covering residency, permanent establishment (PE), business profits, dividends/interest/royalties withholding tax, and mutual agreement procedures (MAP).","seq":0},{"id":1000674,"no":"OECD MTC Art. 4–25","heading":"Key Treaty Articles: Residency, PE, Passive Income & MAP","text":"• Art. 4 (Resident): tie-breaker rules for dual-resident individuals (permanent home, centre of vital interests) and entities (mutual agreement).\n• Art. 5 & Art. 7 (Permanent Establishment & Business Profits): source country may tax business profits ONLY if attributable to a PE (fixed place of business, construction site >12 months, or dependent agent).\n• Arts. 10–12 (Withholding Tax Caps): Dividends (5% substantial holding / 15% portfolio), Interest (10%), Royalties (0% in OECD Model; often 10% in bilateral treaties involving China).\n• Art. 23 & Art. 25: Elimination of double taxation (exemption or credit method) and Mutual Agreement Procedure (MAP) for cross-border dispute resolution.","seq":1},{"id":1000675,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (OECD): https://www.oecd.org/en/topics/sub-issues/oecd-model-tax-convention-on-income-and-on-capital.html\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.","seq":2}]});
